Circles with centers  $A ,~ B,$  and  $C$  each have radius  $r$ , where  $1 < r < 2$ . The distance between each pair of centers is  $2$ . If  $B'$  is the point of intersection of circle  $A$  and circle  $C$  which is outside circle  $B$ , and if  $C'$  is the point of intersection of circle  $A$  and circle  $B$  which is outside circle  $C$ , then length  $B'C'$  equals $\textbf{(A) }3r-2\qquad\textbf{(B) }r^2\qquad\textbf{(C) }r+\sqrt{3(r-1)}\qquad$  $\textbf{(D) }1+\sqrt{3(r^2-1)}\qquad\textbf{(E) }\text{none of these}$ [asy]
//Holy crap, CSE5 is freaking amazing!
import cse5;
pathpen=black;
pointpen=black;
dotfactor=3;
size(200);
pair A=(1,2),B=(2,0),C=(0,0);
D(CR(A,1.5));
D(CR(B,1.5));
D(CR(C,1.5));
D(MP(" $A$ ",A));
D(MP(" $B$ ",B));
D(MP(" $C$ ",C));
pair[] BB,CC;
CC=IPs(CR(A,1.5),CR(B,1.5));
BB=IPs(CR(A,1.5),CR(C,1.5));
D(BB[0]--CC[1]);
MP(" $B'$ ",BB[0],NW);MP(" $C'$ ",CC[1],NE);
//Credit to TheMaskedMagician for the diagram
[/asy]

[asy]
/*Using regular asymptote, this diagram would take 30 min to make. Using cse5, this takes 5 minutes. Conclusion? CSE5 IS THE BEST PACKAGE EVER CREATED!!!!*/
size(100);
import cse5;
pathpen=black;
anglefontpen=black;
pointpen=black;
anglepen=black;
dotfactor=3;
pair A=(0,0),B=(0.5,0.5*sqrt(3)),C=(3,0),D=(1.7,0),EE;
EE=(B+C)/2;
D(MP(" $A$ ",A,W)--MP(" $B$ ",B,N)--MP(" $C$ ",C,E)--cycle);
D(MP(" $E$ ",EE,N)--MP(" $D$ ",D,S));
D(D);D(EE);
MA("80^\circ",8,D,EE,C,0.1);
MA("20^\circ",8,EE,C,D,0.3,2,shift(1,3)*C);
draw(arc(shift(-0.1,0.05)*C,0.25,100,180),arrow =ArcArrow());
MA("100^\circ",8,A,B,C,0.1,0);
MA("60^\circ",8,C,A,B,0.1,0);
//Credit to TheMaskedMagician for the diagram
[/asy]

